function G = ashuganj_grid()
%ASHUGANJ_GRID  External grid equivalent - Ashuganj 450 MW CCPP SOUTH.
%
%   G = ASHUGANJ_GRID() returns the Thevenin equivalent of the PGCB 230 kV
%   network at the plant boundary.
%
%   ============ READ THIS BEFORE USING ANY NUMBER BELOW ============
%   NO VERIFIED PGCB GRID STRENGTH EXISTS IN THE SOURCE SET.
%
%   The 50 kA figure is the ESTIMATED Siemens external-grid source quantity
%   from Generator Data-South §2.4 High voltage network (GRID): UNgrid 230 kV;
%   XN 2,66 estimated [= 2.66, European decimal comma]; Sk 19.919 [= 19,919 MVA,
%   European decimal]; Ik 50 kA. Line 95 prints XN = UNgrid/(3*IK'') with the
%   root symbol lost in extraction; executed math uses √3 giving |Z| =
%   2.65581124 ohm. XN ≈ 2.66 is the separately-reported rounded estimate;
%   |Z| = 2.65581124 is DERIVED via V^2/Ssc — never pair them as an exact R/X.
%   Equipment ratings are documented independently as EQUIPMENT RATINGS
%   (GIS 50 kA / 1 s + 3 s short-time withstand, 125 kA peak withstand,
%   50 kA making) and are NOT the source of this estimate.
%
%   Approved answer Q1a: use the impedance implied by that source quantity ONLY
%   as an explicitly labelled ESTIMATE, never as verified data.  Every result
%   that depends on it must say so.  Its status is therefore ESTIMATED, and it
%   is the single weakest number in the whole model.
%   =================================================================
%
%   Phase 3 (Task 4): the equivalent sits at B230_REMOTE behind the locked
%   0.7 km physical line L_LINE (B230_1 -> B230_REMOTE). Numerical estimate
%   unchanged (ESTIMATED). Q7a history: no 70 km line; pre-Phase-3 the
%   equivalent sat at the plant boundary B230_1.
%
%   See also ASHUGANJ_LINES, ASHUGANJ_MASTER_DATA.

G.Name              = 'EXT_GRID';
G.Label             = 'EXT GRID';
G.Bus_internal      = 'BGRID230';
G.Bus_boundary      = 'B230_1';
G.Bus_remote        = 'B230_REMOTE';   % display only: ZGRID spans BGRID230->B230_REMOTE since Phase-3 Task 4; solver wiring uses port handles, not this string
G.Grid_equivalent_bus = 'B230_REMOTE'; % display/semantic field (REV3.1 reconciliation): grid-equivalent connection bus; solver uses port handles; Bus_boundary kept for legacy fallback
G.Operator          = 'PGCB 230 kV network';

% ---- Voltage -----------------------------------------------------------
G.Vnom_V            = 230000;
G.Vnom_Status       = 'VERIFIED_ENGINEERING_DOCUMENT';
G.Vnom_Source       = 'SLD Rev 03 - 230 kV switchyard nominal voltage';

G.Vset_pu           = 1.00;
G.Vset_V            = G.Vset_pu*G.Vnom_V;
G.Vset_Status       = 'ENGINEERING_ASSUMPTION';
G.Vset_Note         = ['The actual PGCB busbar voltage at Ashuganj is NOT ', ...
                       'documented. 1.00 pu is used. This is a slack-bus ', ...
                       'setpoint, deliberately un-tuned: it is NOT adjusted ', ...
                       'to make plant voltages look good, consistent with ', ...
                       'approved answer Q8a on tap positions. Every solved ', ...
                       'voltage in the model scales essentially linearly ', ...
                       'with this figure, so the reader can rescale.'];
G.PhaseAngle_deg    = 0;
G.PhaseAngle_Status = 'DERIVED_FROM_VERIFIED_DATA';
G.PhaseAngle_Note   = 'Angle reference of the whole study, by definition of the slack bus.';

G.f_Hz              = 50;
G.f_Status          = 'VERIFIED_PLANT';
G.f_Note            = ['50 Hz. The prior CYME PSAF studies in the source set ', ...
                       'were built at 60 Hz (defect D2); that frequency is ', ...
                       'rejected outright, not averaged or reconciled.'];

% ---- Short-circuit level: the ESTIMATE and its provenance -------------
G.Isc_kA            = 50;
G.Isc_Status        = 'ESTIMATED';
G.Isc_Source        = ['Siemens Generator Data-South §2.4 High voltage network (GRID): ', ...
                       'UNgrid 230 kV; XN 2,66 estimated [=2.66]; Sk 19.919 [=19,919 MVA]; ', ...
                       'Ik 50 kA. ESTIMATED Siemens external-grid source quantity. ', ...
                       'Equipment 50 kA/1 s+3 s, 125 kA peak, 50 kA making are ', ...
                       'separate EQUIPMENT RATINGS, not this source.'];
G.Isc_Warning       = ['Treating the §2.4 estimated source quantity as a firm fault level ', ...
                       'assumes the network is exactly as strong as the Siemens estimate. ', ...
                       'That is a source estimate, so this model figure is an ESTIMATE ', ...
                       'on grid strength and therefore a LOWER BOUND on ', ...
                       'grid impedance. Consequence: the model understates ', ...
                       'the boundary voltage deviation caused by plant ', ...
                       'export. Direction of the error is known; magnitude ', ...
                       'is not.'];

G.Ssc_MVA           = sqrt(3)*G.Vnom_V*G.Isc_kA*1000/1e6;
G.Ssc_Status        = 'DERIVED_FROM_VERIFIED_DATA';   % derived FROM AN ESTIMATE
G.Ssc_Derivation    = 'S = sqrt(3) * 230 kV * 50 kA';
G.Ssc_Note          = ['DERIVED_FROM_VERIFIED_DATA describes the ARITHMETIC ', ...
                       'only. The INPUT is ESTIMATED, so the result inherits ', ...
                       'ESTIMATED confidence. Do not quote this as verified.'];

% ---- Equivalent impedance ---------------------------------------------
G.XR_ratio          = inf;
G.XR_Status         = 'ENGINEERING_ASSUMPTION';
G.XR_Note           = ['Q1a approved: X/R is NOT documented, so no ', ...
                       'resistance is invented. R = 0 exactly, giving an ', ...
                       'infinite X/R. MEASURED effect (test_grid_sensitivity ', ...
                       'Part 2, which corrected an earlier wrong claim here ', ...
                       'that the angle shift is "slightly overstated"): the ', ...
                       'boundary ANGLE is essentially INVARIANT under X/R ', ...
                       '(0.0072 deg spread), because holding |Z| fixed pins ', ...
                       'X to within 2 %. What DOES move is the boundary ', ...
                       'voltage MAGNITUDE, and upward - R = 0 OVERSTATES the ', ...
                       'sag, so the model is pessimistic there - together ', ...
                       'with grid losses (zero here, 0.704 MW at X/R = 10) ', ...
                       'and generator MVAr (-16.8 % at X/R = 10). The cause ', ...
                       'is that this plant exports P and Q in a ratio near ', ...
                       '12.6 to 1, so R*P dominates X*Q and the usual ', ...
                       'mostly-reactive transmission intuition inverts. ', ...
                       'See matlab/data/assumptions/grid_series_resistance_zero.m'];

G.R_ohm             = 0;
G.R_Status          = 'ENGINEERING_ASSUMPTION';

G.Z_ohm             = G.Vnom_V^2/(G.Ssc_MVA*1e6);
G.X_ohm             = sqrt(G.Z_ohm^2 - G.R_ohm^2);    % = Z_ohm since R = 0
G.X_Status          = 'ESTIMATED';
G.X_Source          = ['|Z| = V^2/S_sc = 2.65581124 ohm DERIVED from the §2.4 50 kA ', ...
                       'ESTIMATED Siemens source quantity. XN ≈ 2.66 is the ', ...
                       'separately-reported rounded estimate in §2.4, not an R/X pair. ', ...
                       'ESTIMATE, per approved answer Q1a.'];
G.L_H               = G.X_ohm/(2*pi*G.f_Hz);
G.L_Status          = 'DERIVED_FROM_VERIFIED_DATA';
G.L_Derivation      = 'L = X / (2*pi*50)';

% ---- Load-flow representation -----------------------------------------
G.LF_BusType        = 'swing';
G.Model_block       = 'sps_lib/Sources/Three-Phase Source';
G.Model_treatment   = 'ideal source + explicit external series branch';
G.Model_Note        = ['The source itself is IDEAL (NonIdealSource = off) ', ...
                       'and the equivalent impedance is a SEPARATE ', ...
                       'Three-Phase Series RLC Branch between BGRID230 and ', ...
                       'B230_REMOTE (Phase-3; plant bus B230_1 connects via ', ...
                       'the L_LINE PI section). This is deliberate and it matters: SPS ', ...
                       'enforces the swing voltage at the source TERMINAL, ', ...
                       'so an impedance placed INSIDE the source block ', ...
                       'would be bypassed by the load-flow voltage ', ...
                       'constraint and the grid would behave as infinitely ', ...
                       'stiff at B230_REMOTE. Putting it outside makes the ', ...
                       'boundary voltage genuinely respond to plant export.'];
G.InternalConnection = 'Yg';
G.InternalConnection_Status = 'ENGINEERING_ASSUMPTION';
G.InternalConnection_Note   = ['The PGCB 230 kV network is effectively ', ...
                       'solidly earthed, but no earthing document is in the ', ...
                       'set. Yg is used. NO effect on a balanced load flow.'];

G.Qmin_MVAr         = -inf;
G.Qmax_MVAr         =  inf;
G.Qlim_Status       = 'NOT_APPLICABLE';
G.Qlim_Note         = 'A slack bus absorbs whatever the network requires, by definition.';

% ---- Expected effect, stated in advance so the result can be checked --
G.Expected_effect   = ['At full rated export (about 375 MW leaving the GSUT ', ...
                       'HV terminal) the boundary current is roughly 0.94 ', ...
                       'kA and the angle shift across the grid equivalent ', ...
                       'is about atan(P*X/V^2) = atan(375e6*2.656/230e3^2) ', ...
                       'which is near 1.1 deg, with only a small change in ', ...
                       'voltage magnitude. If the solved result departs far ', ...
                       'from this, the model is wrong, not the plant.'];

% ------------------------------------------------------------------------
% Integrity assertions
% ------------------------------------------------------------------------
assert(G.Vnom_V == 230000, 'ashuganj_grid: grid must be at 230 kV. No 400 kV in South scope.');
assert(G.f_Hz == 50, 'ashuganj_grid: grid must be 50 Hz, not the 60 Hz of the prior PSAF studies.');
assert(G.R_ohm == 0, 'ashuganj_grid: R must be 0 per approved answer Q1a.');
assert(G.X_ohm > 0 && G.X_ohm < 100, 'ashuganj_grid: grid X is out of any plausible range.');
assert(strcmp(G.Isc_Status,'ESTIMATED'), ...
    ['ashuganj_grid: the grid short-circuit figure must remain ESTIMATED. ', ...
     'It is the §2.4 Siemens estimated source quantity, not verified PGCB data.']);
assert(strcmp(G.X_Status,'ESTIMATED'), ...
    'ashuganj_grid: grid X must remain ESTIMATED.');
end

function S = ashuganj_phase2_systems(G,A)
%ASHUGANJ_PHASE2_SYSTEMS Isolated metadata-only component configuration.
% S = ashuganj_phase2_systems() uses canonical generator and assumptions.
% S = ashuganj_phase2_systems(G) or ashuganj_phase2_systems(G,A) accepts the
% scalar generator (NOT master) and a complete engineering_assumptions struct.
% Six objects: excitation, sfc, stationDC, governor, pss, dynamicReadiness.
% Numeric/categorical parameters are records; text policies are descriptors.
% No solver, builder, load-flow allocation, field base, or dynamics changed.
% Override value AND selected_value together, retaining schema/units/paths.
% Ranges may narrow/widen inside the central reasonable range. Cross-field
% physical consistency is checked too. Extra/missing keys are rejected.
if nargin < 1
    G = ashuganj_generators();
end
if nargin < 2
    A = engineering_assumptions();
end
machineKeys = {'Snom_MVA','P_capacity_MW','Vnom_kV','H_s','Ra_ohm', ...
    'Ra_pu_machine','Xd','Xdp','Xdpp','Xq','Xqp','Xqpp','Xl', ...
    'Td0p_s','Td0pp_s','Tq0p_s','Tq0pp_s'};
validate_generator(G,machineKeys);
validate_assumptions(A);
S = struct();
keys = fieldnames(A);
for k = 1:numel(keys)
    r = A.(keys{k});
    S = put_record(S,strsplit(r.component_path,'.'),r);
end
source = phase2_source_data(G);
S.excitation.id = 'ACADEMIC_STATIC_EXCITATION';
S.sfc.id = 'ISOLATED_STARTING_CONVERTER';
S.stationDC.id = 'ISOLATED_STATION_DC';
S.governor.id = 'ACADEMIC_GOVERNOR_TURBINE';
S.pss.id = 'DISABLED_GENERIC_PSS';
S.dynamicReadiness.id = 'PRIMARY_MACHINE_READINESS';
S.excitation.type = source_record(source.excitation.type);
S.excitation.designation = source_record(source.excitation.designation);
S.excitation.no_load_voltage_V = source_record(source.excitation.no_load_voltage_V);
S.excitation.model = 'GENERIC_TWO_LAG_NOT_IDENTIFIED_SEMIPOL_MODEL';
S.excitation.field.physical_base = 'UNRESOLVED_NOT_USED';
S.excitation.field.normalization = 'ABSTRACT_NO_LOAD_EFD_NOT_122V_NOT_RATED_FIELD';
S.excitation.avr.equation = 'Tavr*dVr/dt=Kavr*(Vref-Vt)-Vr; Tfield*dEfd/dt=Vr_limited-Efd';
S.excitation.avr.state_policy = 'BOUNDED_LAG_STATES_NO_HIDDEN_INTEGRATOR_WINDUP';
S.excitation.oel.input_definition = 'Efd/rated_field_reference_pu; NOT Efd/no_load_reference_pu';
S.excitation.oel.equation = 'Lag bounded gain*max(Efd/rated_field_reference_pu-threshold_pu,0); subtract correction';
S.excitation.uel.equation = 'Qboundary=interp1(source_P,source_Qmin,P)+inset_MVAr; lag bounded gain*max(Qboundary-Q,0); add correction';
S.excitation.uel.domain_policy = 'REJECT_OUTSIDE_CURVE_OR_PRIMARY_CAPACITY; REPORT_INFEASIBLE_INSET_NOT_CLIP';
S.excitation.uel.curve = curve_records(G.capabilityCurve);
S.excitation.stator.current_base = 'Snom_MVA/(sqrt(3)*Vnom_kV) kA; primary machine base';
S.excitation.stator.active_overload_action = 'DISPATCH_ACTION_NOT_EXCITATION_REPAIR';
S.excitation.stator.response_policy = 'BOUNDED_REACTIVE_CORRECTION_ONLY; ACTIVE_CURRENT_EXCESS_REPORTED';
S.excitation.limiters.coordination = 'REPORT_CONFLICTS; NO_CLOSED_LOOP_TUNING_OR_STABILITY_CLAIM';
S.sfc.dc_link_kV = source_record(source.sfc.dc_link_kV);
S.sfc.max_starting_output_A = source_record(source.sfc.max_starting_output_A);
S.sfc.power_limit_side = 'OUTPUT';
S.sfc.accounting = 'Pinput=Poutput/efficiency; no DC-current inference from OUTPUT current';
S.sfc.electrical_boundary = 'NO_GENERATOR_FIELD_OR_STATION_DC_CONNECTION';
S.stationDC.electrical_boundary = 'ISOLATED_NO_FIELD_OR_SFC_CONNECTION';
S.stationDC.accounting = 'NOT_ADDED_TO_FROZEN_14MW_AUXILIARY';
S.stationDC.battery.ocv_interpolation = 'linear';
S.stationDC.battery.sign_convention = 'POSITIVE_CURRENT_DISCHARGES_BANK';
S.stationDC.battery.equation = 'Vterminal=OCV(SOC)-I*Rbank; dSOC/dt=-I/(3600*capacity_Ah) for discharge; charge uses charge_efficiency';
S.stationDC.battery.cutoff_policy = 'STOP_DISCHARGE_AT_SOC_MIN_OR_TERMINAL_CUTOFF; STOP_CHARGE_AT_SOC_MAX; REJECT_INVALID_STATE_TIME';
S.stationDC.charger.mode = 'DUTY_STANDBY';
S.stationDC.charger.rating_side = 'DC_OUTPUT_PER_UNIT';
S.stationDC.charger.equation = 'Lag bounded voltage_gain*(Vfloat-Vbus); simultaneous current and Pdc/Vbus bounds; Pac=Pdc/efficiency';
S.stationDC.charger.full_soc_policy = 'SUPPLY_LOAD_ONLY_AT_FULL_SOC; NO_FORCED_OVERVOLTAGE_OR_OVERCHARGE';
S.stationDC.charger.redundancy = 'STANDBY_REPLACES_FAILED_DUTY_NOT_PARALLEL_DOUBLE_OUTPUT';
S.stationDC.loads.excitation_electronics_scope = 'AUXILIARY_ELECTRONICS_NOT_FIELD_POWER';
S.stationDC.loads.pulse_policy = 'TRIP_AND_CLOSE_ADDITIONAL_NONREPEATING_PULSES_WITH_SEPARATE_DURATIONS';
S.stationDC.loads.emergency_policy = 'ADDITIONAL_SWITCHED_LOAD_FOR_CALLER_SELECTED_DURATION';
S.governor.max_power_MW = source_record(source.generator.P_capacity_MW);
S.governor.power_base_MVA = source_record(source.generator.Snom_MVA);
S.governor.model = 'GENERIC_DROOP_TWO_LAG_READINESS_ONLY';
S.governor.equation = 'Power-pu correction=(speed_reference_pu-speed_pu)/droop_pu; governor then turbine lag; clamp to primary MW bounds';
S.pss.tuning = 'UNTUNED_GENERIC_DISABLED';
S.pss.input = 'SPEED_DEVIATION_PU';
S.pss.model = 'GENERIC_WASHOUT_TWO_LEAD_LAG_NOT_PLANT_PSS';
S.dynamicReadiness.dataset_id = G.Dataset_ID;
S.dynamicReadiness.model = 'STANDARD_SIXTH_ORDER';
S.dynamicReadiness.validation = 'DATA_ONLY_NOT_DYNAMICALLY_VALIDATED';
S.dynamicReadiness.reactance_selection = 'PRIMARY_UNQUALIFIED_NOT_SATURATED_REPLACEMENT';
S.dynamicReadiness.field_base = 'UNRESOLVED_NOT_USED';
S.dynamicReadiness.unresolved = 'Damping, OCC, detailed rotor circuit and physical field base remain unresolved; no invented zero defaults';
for k = 1:numel(machineKeys)
    key = machineKeys{k};
    S.dynamicReadiness.machine.(key) = source_record(source.generator.(key));
end
for key = {'Xdpp_sat','S10','S12'}
    S.dynamicReadiness.saturation.(key{1}) = source_record(source.generator.(key{1}));
end
S.dynamicReadiness.saturation.policy = 'SOURCE_COEFFICIENTS_AND_SATURATED_XDPP_SEPARATE_NOT_REPLACEMENT_OR_FULL_OCC';
f = phase2_parameter(G.f_Hz,'Hz','Generator Name Plate_South.pdf', ...
    'Existing ashuganj_generators transcription: f_Hz / f_Status',G.f_Status, ...
    'Existing primary transcription','Rated frequency retained; no new attachment inspection.');
S.dynamicReadiness.frequency_Hz = source_record(f);
end

function validate_generator(G,keys)
try
    assert(isstruct(G) && isscalar(G));
    assert(all(isfield(G,{'Primary','Provenance','Dataset_ID','capabilityCurve', ...
        'Uexc0_V','SFC_DC_link_kV','SFC_Imax_A','f_Hz','f_Status'})));
    for key = [keys {'Xdpp_sat','S10','S12'}]
        n = key{1}; v = G.(n);
        assert(isnumeric(v) && isreal(v) && isscalar(v) && isfinite(v) && v>0);
        assert(isequal(v,G.Provenance.(n).Normalized_value));
        if isfield(G.Primary,n)
            assert(isequal(v,G.Primary.(n)));
        end
    end
    for key = {'Uexc0_V','SFC_DC_link_kV','SFC_Imax_A','f_Hz'}
        v = G.(key{1});
        assert(isnumeric(v) && isscalar(v) && isreal(v) && isfinite(v) && v>0);
    end
    assert(G.P_capacity_MW<=G.Snom_MVA);
    generatorCapability(G.P_capacity_MW,G.capabilityCurve);
catch
    error('ashuganj_phase2_systems:InvalidGenerator', ...
        'Require scalar canonical generator with finite primary inputs consistent with its provenance.');
end
end

function validate_assumptions(A)
D = engineering_assumptions(); keys = fieldnames(D);
try
    assert(isstruct(A) && isscalar(A) && isequal(sort(fieldnames(A)),sort(keys)));
    for k = 1:numel(keys)
        key = keys{k}; r = A.(key); d = D.(key);
        assert(isstruct(r) && isscalar(r) && all(isfield(r,fieldnames(d))));
        assert(strcmp(r.status,'ENGINEERING_ASSUMPTION') && strcmp(r.source_status,r.status));
        assert(strcmp(r.unit,d.unit) && strcmp(r.assumption_key,key) && ...
            strcmp(r.component_path,d.component_path));
        assert(isequal(size(r.value),size(d.value)) && isequal(r.selected_value,r.value));
        assert(isequal(r.reasonable_range,d.reasonable_range));
        phase2_parameter(r.value,r.unit,r.source,r.source_locator,r.status,r.confidence, ...
            r.rationale,'assumption_basis',r.assumption_basis, ...
            'reasonable_range',r.reasonable_range,'assumed_range',r.assumed_range, ...
            'source_status',r.source_status,'derivation',r.derivation, ...
            'interpretation_status',r.interpretation_status);
    end
catch
    error('ashuganj_phase2_systems:InvalidAssumptions', ...
        'Require complete central keys, metadata, stable units/paths and finite selected values within approved reasonable ranges.');
end
v = @(key) A.(key).value;
consistent = v('exc_command_min_pu')<v('exc_command_max_pu') && ...
    v('exc_no_load_reference_pu')<v('exc_oel_rated_field_reference_pu') && ...
    v('exc_oel_rated_field_reference_pu')*v('exc_oel_threshold_pu')<v('exc_command_max_pu') && ...
    v('exc_limiter_min_correction_pu')<v('exc_limiter_max_correction_pu') && ...
    v('sfc_min_output_power_MW')<v('sfc_max_output_power_MW') && ...
    isequal(v('dc_ocv_soc'),[0 1]) && all(diff(v('dc_ocv_V'))>0) && ...
    v('dc_soc_min')<v('dc_soc_max') && v('dc_soc_initial')>=v('dc_soc_min') && ...
    v('dc_soc_initial')<=v('dc_soc_max') && ...
    v('dc_cutoff_voltage_V')>=min(v('dc_ocv_V')) && ...
    v('dc_cutoff_voltage_V')<max(v('dc_ocv_V')) && ...
    v('charger_float_voltage_V')>max(v('dc_ocv_V')) && ...
    v('charger_nominal_voltage_V')==v('dc_nominal_voltage_V') && ...
    v('charger_min_current_A')<v('charger_max_current_A') && ...
    v('charger_max_current_A')*v('charger_float_voltage_V')>=1000*v('charger_rated_power_kW') && ...
    v('dc_max_charge_A')<=v('charger_max_current_A') && ...
    v('pss_output_min_pu')<v('pss_output_max_pu');
continuous = v('load_relay_kW')+v('load_control_kW')+v('load_instrumentation_kW')+ ...
    v('load_communications_kW')+v('load_emergency_control_kW')+v('load_excitation_electronics_kW');
peak = continuous+v('load_trip_kW')+v('load_close_kW')+v('load_emergency_additional_kW');
% Cutoff is the worst-case current demand over the cutoff-to-float envelope.
% One duty unit must cover peak without battery or standby assistance.
consistent = consistent && peak<v('charger_rated_power_kW') && ...
    1000*peak<=v('charger_max_current_A')*v('dc_cutoff_voltage_V') && ...
    1000*peak/v('dc_cutoff_voltage_V')<v('dc_max_discharge_A');
if ~consistent
    error('ashuganj_phase2_systems:InconsistentConfiguration', ...
        'Individually ranged selections violate field, SOC/OCV, charger, or load-budget relationships.');
end
end

function s = put_record(s,parts,r)
name = parts{1};
if numel(parts)==1
    s.(name) = r;
else
    if ~isfield(s,name)
        s.(name) = struct();
    end
    s.(name) = put_record(s.(name),parts(2:end),r);
end
end

function r = source_record(old)
% Range for source scalars is fixed selection, not invented measurement error.
r = old;
r.raw_source = old;
% Recognize primary evidence before considering interpretation qualifiers.
switch old.source_status
    case {'VERIFIED_PLANT','VERIFIED_PROJECT_DATA', ...
            'VERIFIED_ENGINEERING_DOCUMENT','PRIMARY_VERIFIED'}
        status = 'PRIMARY_VERIFIED';
    case {'DERIVED_FROM_VERIFIED_DATA','PRIMARY_SOURCE_QUALIFIED', ...
            'PRIMARY_SOURCE_EXTRACTED'}
        status = 'PRIMARY_SOURCE_QUALIFIED';
    otherwise
        error('ashuganj_phase2_systems:InvalidGenerator', ...
            'Unrecognized or non-primary source status: %s.',old.source_status);
end
if strcmp(old.interpretation_status,'QUALIFIED')
    status = 'PRIMARY_SOURCE_QUALIFIED';
end
r.status = status;
r.source_status = status;
if isnumeric(r.value)
    r.reasonable_range = [min(r.value(:)) max(r.value(:))];
    r.assumed_range = r.reasonable_range;
    r.range_basis = 'FIXED_SOURCE_SELECTION_NOT_UNCERTAINTY_OR_OPERATING_RANGE';
else
    r.reasonable_range = [];
    r.assumed_range = [];
    r.range_basis = 'CATEGORICAL_SOURCE_VALUE_NUMERIC_RANGE_NOT_APPLICABLE';
end
% Existing raw_provenance is retained alongside the untouched normalized view.
end

function C = curve_records(raw)
C.raw_source = raw;
C.interpolation = raw.interpolation;
C.extrapolation = raw.extrapolation;
for key = {'P_MW','Qmin_MVAr','Qmax_MVAr'}
    n = key{1}; unit = raw.Q_unit;
    if strcmp(n,'P_MW')
        unit = raw.P_unit;
    end
    v = raw.(n); bounds = [min(v) max(v)];
    r = phase2_parameter(v,unit,raw.source,raw.source_locator, ...
        'PRIMARY_SOURCE_QUALIFIED',raw.confidence,raw.rationale, ...
        'reasonable_range',bounds,'assumed_range',bounds, ...
        'interpretation_status','QUALIFIED');
    r.qualification = 'PRIMARY_SOURCE_EXTRACTED';
    r.range_basis = 'EXTRACTED_ARRAY_EXTENT_NOT_MEASUREMENT_UNCERTAINTY';
    C.(n) = r;
end
end

function L = ashuganj_lines()
%ASHUGANJ_LINES  Line / cable / series-branch database - Ashuganj SOUTH.
%
%   L = ASHUGANJ_LINES() returns a struct array of every series branch that
%   is NOT a transformer.  Most entries are deliberately zero-impedance: the
%   South plant is a compact single-shaft block with GIS, so the electrical
%   distances are short AND, more importantly, no cable or busduct impedance
%   is documented anywhere in the source set.  Rather than invent lengths and
%   impedances, those connections are modelled as direct nodes-in-common and
%   the omission is stated.
%
%   Approved answer Q7a: NO 70 km transmission line to a remote grid bus is
%   created.  The external-grid equivalent sits at the PLANT BOUNDARY.  The
%   one genuinely modelled series impedance is therefore the grid equivalent
%   itself, and it is an ESTIMATE, clearly labelled (approved answer Q1a).
%
%   See also ASHUGANJ_GRID, ASHUGANJ_MASTER_DATA.

k = 0; L = struct([]);

% =====================================================================
% 1.  The external grid equivalent series branch  (MODELLED)
% =====================================================================
% Placed as an EXPLICIT branch rather than inside the source block, because
% SPS enforces the swing voltage at the source TERMINAL: an internal source
% impedance would be short-circuited by the load-flow voltage constraint and
% would have no effect on the solved plant-boundary voltage.
k=k+1;
L(k).Name              = 'ZGRID';
L(k).Label             = 'GRID EQUIV Z';
L(k).Bus_from          = 'BGRID230';
L(k).Bus_to            = 'B230_REMOTE';
L(k).Placement_Note    = ['Phase-3: grid equivalent moved to remote bus; ', ...
                          'plant bus connects via L_LINE.'];
L(k).Vnom_V            = 230000;
L(k).Model_included    = true;
L(k).Model_block       = 'sps_lib/Passives/Three-Phase Series RLC Branch';
L(k).BranchType        = 'L';       % pure inductance: R is zero by Q1a
L(k).R_ohm             = 0;
L(k).R_Status          = 'ENGINEERING_ASSUMPTION';
L(k).R_Note            = ['Q1a approved: the grid X/R ratio is NOT ', ...
                          'documented, so no resistance is invented. R = 0 ', ...
                          'makes the grid equivalent purely reactive, which ', ...
                          'is the standard treatment when X/R is unknown ', ...
                          'and which slightly OVERSTATES the reactive ', ...
                          'coupling and UNDERSTATES grid losses. See ', ...
                          'matlab/data/assumptions/grid_series_resistance_zero.m'];
L(k).X_ohm             = [];        % filled below from the grid data
L(k).X_Status          = 'ESTIMATED';
L(k).Length_km         = 0;
L(k).Length_Status     = 'NOT_APPLICABLE';
L(k).Length_Note       = ['Zero by construction. This is a Thevenin ', ...
                          'EQUIVALENT at the plant boundary, not a physical ', ...
                          'line, so it has no length, no charging ', ...
                          'capacitance and no thermal rating (Q7a).'];
L(k).C_F               = 0;
L(k).C_Status          = 'NOT_APPLICABLE';

% =====================================================================
% 1b. Locked 0.7 km lumped dual-circuit PI line  (MODELLED, Phase 3)
% =====================================================================
k=k+1;
L(k).Name = 'L_LINE';
L(k).Label = 'SOUTH GIS TO GRID 0.7KM D/C EQ (MALLARD REF)';
L(k).Bus_from = 'B230_1';
L(k).Bus_to = 'B230_REMOTE';
L(k).Vnom_V = 230000;
L(k).Model_included = true;
L(k).Model_block = 'sps_lib/Passives/Three-Phase PI Section Line';
L(k).BranchType = 'PI';
L(k).Length_km = 0.7;
L(k).Length_Status = 'ENGINEERING_ASSUMPTION';
L(k).Length_Note = 'Locked Phase-3 EA: 0.7 km GIS-to-grid; INEL-112070-00-ELC-DE-0026 unavailable. 70 km retained only as documented 400-kV/North conflict; 44 km is the separate Ghorasal line.';
L(k).Physical_circuit_count = 2;
L(k).Model_representation = 'LUMPED_DUAL_CIRCUIT_PI';
L(k).Conductor_reference = 'MALLARD_795_MCM';
L(k).Conductor_Status = 'ENGINEERING_ASSUMPTION';
L(k).R_ohm = 0.0277725;  L(k).R_Status = 'ENGINEERING_ASSUMPTION';
L(k).R_Note = 'DERIVED_FROM_ENGINEERING_REFERENCE (human tier): (0.00015 pu/km*529)/2*0.7; ref Ghorasal-Mallard PGCB/JICA, NOT measured South link.';
L(k).X_ohm = 0.1425655;  L(k).X_Status = 'ENGINEERING_ASSUMPTION';
L(k).X_Note = 'DERIVED_FROM_ENGINEERING_REFERENCE (human tier): (0.00077 pu/km*529)/2*0.7; same reference.';
L(k).C_F = 3.937996e-6/(2*pi*50);  L(k).C_Status = 'ENGINEERING_ASSUMPTION';
L(k).C_Note = 'DERIVED_FROM_ENGINEERING_REFERENCE (human tier): B=3.937996 uS (2x1.968998) at 50 Hz; C=B/(2*pi*50).';
L(k).R0_ohm = NaN; L(k).R0_Status = 'MISSING';
L(k).X0_ohm = NaN; L(k).X0_Status = 'MISSING';
L(k).C0_F = NaN;   L(k).C0_Status = 'MISSING';

% =====================================================================
% 2.  230 kV GIS internal connections  (zero impedance)
% =====================================================================
k=k+1;
L(k).Name              = 'BAY_GSUT';
L(k).Label             = 'BAY 10BAY11';
L(k).Bus_from          = 'B230_1';
L(k).Bus_to            = 'GSUT_HV';
L(k).Vnom_V            = 230000;
L(k).Model_included    = false;
L(k).Model_treatment   = 'direct connection (zero impedance)';
L(k).Rated_A           = 2000;
L(k).Rated_A_Status    = 'VERIFIED_ENGINEERING_DOCUMENT';
L(k).Rated_A_Source    = ['GIS Data Sheet_230KV Generator Transformer module 2000 A ', ...
                          '(REV3 §3.6 units-column audit; Line module 2000 A, ', ...
                          'Bus coupler module 3150 A — 3150 A is coupler/busbar only). ', ...
                          'Conductor ampacity MISSING, never this module rating.'];
L(k).Exclusion_reason  = ['GIS bay 10BAY11 (Q0 circuit-breaker, Q1 to ', ...
                           'BUS 2, Q2 to BUS 1, Q9 earthing switch). The ', ...
                           'busduct and bay impedances are MISSING and are ', ...
                           'in any case negligible against the GSUT 16 %%. ', ...
                           'The GSUT HV terminal is therefore the SAME ', ...
                           'electrical node as B230_1.'];
L(k).Notes             = ['Double-busbar single-breaker: the bay can be ', ...
                          'selected to BUS 1 or BUS 2 via Q2/Q1. Approved ', ...
                          'answer Q10a: with the coupler closed the ', ...
                          'selection does not materially affect the ', ...
                          'balanced network, so GSUT is shown on BUS 1.'];

k=k+1;
L(k).Name              = 'BAY_GAT';
L(k).Label             = 'BAY 10BAY20';
L(k).Bay_label_note    = ['REV3.1 reconciliation: Label corrected 10BAY12->10BAY20 per ', ...
                          'REV3 C-17 (BAY_GAT=10BAY20) + GIS SLD GAT(F13) 10BAY20 + builder ', ...
                          'GAT BAY CB 10BAY20 convention. Prior 10BAY12 was the bus-coupler/protection ', ...
                          'panel designation, not the GAT bay — recorded as panel-label conflict, now resolved.'];
L(k).Bus_from          = 'B230_2';
L(k).Bus_to            = 'GAT_HV';
L(k).Vnom_V            = 230000;
L(k).Model_included    = false;
L(k).Model_treatment   = 'direct connection (zero impedance) + switching breaker';
L(k).Rated_A           = 2000;
L(k).Rated_A_Status    = 'VERIFIED_ENGINEERING_DOCUMENT';
L(k).Rated_A_Source    = ['Transformer-bay class 2000 A: GIS SLD shows GAT(F13) 10BAY20 with Q0 breaker ', ...
                          '(same Q0 designation as GSUT bay); CB datasheet headed TRANSFORMER BAY carries ', ...
                          '2000 A continuous (REV3 §3.6b/C-36, Q0-verified); module table GT 2000 A / Line 2000 A / ', ...
                          'Coupler 3150 A (REV3 §3.6). Conductor ampacity MISSING, never this module rating.'];
L(k).Exclusion_reason  = ['As BAY_GSUT. The bay IMPEDANCE is omitted, but ', ...
                          'the bay CIRCUIT-BREAKER is modelled explicitly ', ...
                          'because approved answer Q4c requires the GAT to ', ...
                          'be switched in and out between cases.'];
L(k).Notes             = 'GAT shown on BUS 2 so that the loop crosses the coupler.';

k=k+1;
L(k).Name              = 'BAY_GRID';
L(k).Label             = 'LINE BAY (bay number MISSING — NOT 10BAY20)';
L(k).Bay_label_note    = ['REV3.1 reconciliation: prior Label BAY 10BAY20 collided with corrected BAY_GAT=10BAY20; ', ...
                          '10BAY11/12/20 are GSUT/coupler/GAT per SLD+builder convention, so the outgoing line-bay number ', ...
                          'is MISSING (INEL-0026 unavailable). Label carries the conflict note, not a bay number.'];
L(k).Bus_from          = 'B230_1';
L(k).Bus_to            = 'GRID_TIE';
L(k).Vnom_V            = 230000;
L(k).Model_included    = false;
L(k).Model_treatment   = 'direct connection (zero impedance)';
L(k).Rated_A           = 2000;
L(k).Rated_A_Status    = 'VERIFIED_ENGINEERING_DOCUMENT';
L(k).Rated_A_Source    = ['GIS Data Sheet_230KV Line module 2000 A (REV3 §3.6 units-column audit; ', ...
                          'GT module 2000 A, Bus coupler module 3150 A — 3150 A is coupler/busbar only). ', ...
                          'Conductor ampacity MISSING, never this module rating.'];
L(k).Exclusion_reason  = 'As BAY_GSUT.';
L(k).Notes             = 'Outgoing line bay towards the PGCB 230 kV network.';

% =====================================================================
% 3.  22 kV isolated-phase busduct  (zero impedance)
% =====================================================================
k=k+1;
L(k).Name              = 'IPB22';
L(k).Label             = '22 kV IPB';
L(k).Bus_from          = 'B22';
L(k).Bus_to            = 'B22';
L(k).Vnom_V            = 22000;
L(k).Model_included    = false;
L(k).Model_treatment   = 'direct connection (zero impedance)';
L(k).Rated_A           = 12400;
L(k).Rated_A_Status    = 'VERIFIED_ENGINEERING_DOCUMENT';
L(k).Exclusion_reason  = ['Isolated-phase busduct linking generator, GCB, ', ...
                          'GSUT LV and UAT HV. Its impedance is MISSING and ', ...
                          'is physically a few metres of very large ', ...
                          'conductor. All four terminals are treated as one ', ...
                          'node, B22.'];
L(k).Notes             = ['The generator circuit-breaker (12.4 kA) sits in ', ...
                          'this busduct. It is CLOSED in every load-flow ', ...
                          'case - a load flow of a generating unit with an ', ...
                          'open GCB would be a different study.'];

% =====================================================================
% 4.  6.6 kV feeder cables to the segregated load nodes  (zero impedance)
% =====================================================================
for nm = {'WI1','WI2'}
    k=k+1;
    L(k).Name              = ['FDR_' nm{1}];
    L(k).Label             = ['6.6 kV FDR ' nm{1}];
    L(k).Bus_from          = 'B6_6';
    L(k).Bus_to            = ['B6_6_' nm{1}];
    L(k).Vnom_V            = 6600;
    L(k).Model_included    = false;
    L(k).Model_treatment   = 'direct connection (zero impedance)';
    L(k).Rated_A           = NaN;
    L(k).Rated_A_Status    = 'MISSING';
    L(k).Exclusion_reason  = ['Feeder cable size, length and impedance are ', ...
                              'ALL MISSING. Modelling a cable would mean ', ...
                              'inventing three quantities. The node is ', ...
                              'therefore connected with zero impedance, ', ...
                              'which means the Q6B load split SEGREGATES ', ...
                              'the load for reporting but does NOT make it ', ...
                              'electrically remote: all three 6.6 kV nodes ', ...
                              'solve to the same voltage. This limitation ', ...
                              'is stated in the results report - the split ', ...
                              'is honest about motor grouping, not about ', ...
                              'feeder voltage drop.'];
    L(k).Notes             = 'Water-intake / large-motor group feeder (Q6B).';
end

% =====================================================================
% Fill the one modelled impedance from the grid database, so the number
% exists in exactly ONE place.
% =====================================================================
Gr = ashuganj_grid();
L(1).X_ohm    = Gr.X_ohm;
L(1).L_H      = Gr.L_H;
L(1).X_Status = Gr.X_Status;
L(1).X_Source = Gr.X_Source;

% ------------------------------------------------------------------------
% Integrity assertions
% ------------------------------------------------------------------------
assert(numel(unique({L.Name})) == numel(L), 'ashuganj_lines: duplicate name.');
assert(numel(L) == 8, ...
    'ashuganj_lines: register holds 8 entries (7 Phase-2 + L_LINE).');
assert(sum([L.Model_included]) == 2, ...
    'ashuganj_lines: exactly two series branches should be modelled (ZGRID + L_LINE).');
assert(L(1).R_ohm == 0, 'ashuganj_lines: grid R must be 0 per approved answer Q1a.');
assert(L(1).X_ohm > 0, 'ashuganj_lines: grid X must be positive.');
assert(~any([L.Vnom_V] > 230000), ...
    'ashuganj_lines: a branch above 230 kV was defined. No 400 kV in South scope.');
end

function Ld = ashuganj_loads()
%ASHUGANJ_LOADS  Load database - Ashuganj 450 MW CCPP SOUTH.
%
%   Ld = ASHUGANJ_LOADS() returns a struct array of the auxiliary loads.
%
%   TOTAL AUXILIARY LOAD: 14 MW at 0.85 power factor.
%   ------------------------------------------------------------------
%   A WARNING about this number, carried from the audit: 14 MW happens to be
%   numerically equal to the UAT no-load loss expressed in kW (14 kW) and to
%   3.60 % of the 389.30 MW rated output.  Those are COINCIDENCES.  The 14 MW
%   is the documented plant auxiliary load; the 14 kW is the UAT iron loss.
%   They are unrelated quantities that share two digits, and the resemblance
%   was checked and dismissed during the audit rather than being allowed to
%   propagate as a transcription error.
%
%   ALLOCATION (approved answer Q6B): the load is DISTRIBUTED across three
%   6.6 kV nodes in the ratio 9050 : 2500 : 2500, which comes from the
%   documented motor ratings (kW) of the main auxiliary group and the two
%   water-intake / large-motor groups.  The RATIO is grounded in documented
%   motor ratings; the ALLOCATION OF THE 14 MW TOTAL ACROSS THAT RATIO IS AN
%   APPROVED ASSUMPTION, because no per-node metered demand exists.  The user
%   required this to be labelled an assumption and it is:
%       matlab/data/assumptions/aux_load_allocation_split.m
%
%   Because the 6.6 kV feeder impedances are MISSING (see ASHUGANJ_LINES),
%   the three nodes are joined with zero impedance.  The split therefore
%   segregates the load for REPORTING and for the later protection study; it
%   does not produce feeder voltage drop.  Total P and Q drawn from the UAT
%   are identical to the single-bus case - that is a correctness property,
%   not a defect, and it is stated in the report.
%
%   POWER FACTOR: 0.85 lagging is applied to every node.  A per-node power
%   factor is NOT documented; using one figure for all three nodes avoids
%   inventing three.
%
%   LOAD MODEL: constant PQ.  A load flow that used constant impedance would
%   silently reduce the auxiliary demand whenever the solved voltage sagged,
%   which would flatter the result.  Constant PQ holds the documented demand.
%
%   See also ASHUGANJ_MASTER_DATA, ASHUGANJ_BUSES.

% ---- Documented totals -------------------------------------------------
P_total_MW  = 14.0;
P_Status    = 'VERIFIED_PROJECT_DATA';
P_Source    = 'Project data set - plant auxiliary load 14 MW';
pf          = 0.85;
pf_Status   = 'VERIFIED_PROJECT_DATA';
pf_Source   = 'Project data set - auxiliary load power factor 0.85 lagging';

Q_total_MVAr = P_total_MW*tan(acos(pf));

% ---- Allocation ratio from documented motor ratings (kW) ---------------
alloc_kW    = [9050, 2500, 2500];
alloc_nodes = {'B6_6', 'B6_6_WI1', 'B6_6_WI2'};
alloc_label = {'MV BUS aux group', 'Water intake / motor group 1', ...
               'Water intake / motor group 2'};
share       = alloc_kW/sum(alloc_kW);

k = 0; Ld = struct([]);
for i = 1:numel(alloc_nodes)
    k=k+1;
    Ld(k).Name             = ['LOAD_' alloc_nodes{i}];
    Ld(k).Label            = alloc_label{i};
    Ld(k).Bus              = alloc_nodes{i};
    Ld(k).Vnom_V           = 6600;
    Ld(k).Vnom_Status      = 'VERIFIED_ENGINEERING_DOCUMENT';
    Ld(k).Vnom_Note        = ['The load NOMINAL voltage is the 6.6 kV system ', ...
                              'nominal, not the 6.9 kV UAT winding voltage. ', ...
                              'These are different things (conflict C13) and ', ...
                              'both are used, each in its correct place.'];
    Ld(k).f_Hz             = 50;

    Ld(k).Alloc_kW         = alloc_kW(i);
    Ld(k).Alloc_Status     = 'VERIFIED_PROJECT_DATA';
    Ld(k).Alloc_Source     = 'Documented motor ratings, project data set';
    Ld(k).Share            = share(i);
    Ld(k).Share_Status     = 'DERIVED_FROM_VERIFIED_DATA';

    Ld(k).P_MW             = P_total_MW*share(i);
    Ld(k).P_Status         = 'ENGINEERING_ASSUMPTION';
    Ld(k).P_Source         = ['14 MW documented total apportioned by the ', ...
                              'documented motor-rating ratio ', ...
                              '9050:2500:2500. Approved answer Q6B.'];
    Ld(k).Q_MVAr           = Q_total_MVAr*share(i);
    Ld(k).Q_Status         = 'DERIVED_FROM_VERIFIED_DATA';
    Ld(k).Q_Source         = 'P * tan(acos(0.85)) with P as above';

    Ld(k).pf               = pf;
    Ld(k).pf_Status        = pf_Status;
    Ld(k).pf_Source        = pf_Source;

    Ld(k).Model_included   = true;
    Ld(k).Model_block      = 'sps_lib/Passives/Three-Phase Parallel RLC Load';
    Ld(k).LoadType         = 'constant PQ';
    Ld(k).Configuration    = 'Y (grounded)';
    Ld(k).Config_Status    = 'ENGINEERING_ASSUMPTION';
    Ld(k).Config_Note      = ['The 6.6 kV auxiliary system earthing ', ...
                              'arrangement is not documented in the ', ...
                              'available set. Y(grounded) is used. It has ', ...
                              'NO effect on a balanced load flow (no ', ...
                              'zero-sequence current flows in a balanced ', ...
                              'network); it WOULD matter for the later ', ...
                              'earth-fault study, and it is flagged there.'];
    Ld(k).C_MVAr           = 0;
    Ld(k).C_Status         = 'VERIFIED_PROJECT_DATA';
    Ld(k).C_Note           = ['No power-factor correction or capacitor bank ', ...
                              'appears anywhere in the source set, so none ', ...
                              'is modelled.'];
end

% ---- Documented loads NOT modelled ------------------------------------
k=k+1;
Ld(k).Name             = 'LOAD_B0_4';
Ld(k).Label            = '400 V LV board load';
Ld(k).Bus              = 'B0_4';
Ld(k).Vnom_V           = 400;              % FOUR HUNDRED VOLTS
Ld(k).Vnom_Status      = 'VERIFIED_ENGINEERING_DOCUMENT';
Ld(k).f_Hz             = 50;
Ld(k).P_MW             = NaN;
Ld(k).P_Status         = 'MISSING';
Ld(k).Q_MVAr           = NaN;
Ld(k).Q_Status         = 'MISSING';
Ld(k).Model_included   = false;
Ld(k).Exclusion_reason = ['The 6.6/0.4 kV unit-substation transformers are ', ...
                          'not characterised (C16), and the LV board demand ', ...
                          'is not separately documented. The LV load is ', ...
                          'already inside the 14 MW total and is therefore ', ...
                          'represented AT 6.6 kV. Nothing is lost from the ', ...
                          'power balance; what is lost is the LV voltage ', ...
                          'profile, which this study does not claim to ', ...
                          'produce.'];
Ld(k).Notes            = '400 V. FOUR HUNDRED VOLTS. Not 400 kV.';

